WITH latest_breadth AS (SELECT snapshot_date, sector, pct_above_50dma, change_5d, breadth_signal FROM breadth.sector_daily WHERE snapshot_date = (SELECT MAX(snapshot_date) FROM breadth.sector_daily)),
latest_stage AS (SELECT snapshot_date, sector, AVG(stage2_pct) AS avg_stage2_pct FROM breadth.ma_pct_above WHERE snapshot_date = (SELECT MAX(snapshot_date) FROM breadth.ma_pct_above) GROUP BY snapshot_date, sector)
SELECT b.sector, b.pct_above_50dma, b.change_5d, b.breadth_signal, s.avg_stage2_pct FROM latest_breadth b JOIN latest_stage s ON b.sector = s.sector ORDER BY s.avg_stage2_pct DESC LIMIT 10;
